INSERT INTO resources (section, title, source, description, type, level, tags, meta, url, is_team_pick) VALUES
('university', 'CS229 · Machine Learning', 'Stanford / Andrew Ng', 'The gold-standard academic ML course covering supervised, unsupervised, and reinforcement learning with rigorous math.', 'material', 'Advanced', '["machine-learning","supervised","unsupervised","stanford"]', '["12 weeks","Lecture notes & problem sets"]', 'https://cs229.stanford.edu/', 0),
('university', 'CS50''s Introduction to AI with Python', 'Harvard', 'Harvard''s hands-on introduction to AI concepts using Python — graph search, neural nets, NLP, and more.', 'material', 'Beginner', '["python","search","neural-networks","nlp","harvard"]', '["7 weeks","Free certificate available"]', 'https://pll.harvard.edu/course/cs50s-introduction-artificial-intelligence-python', 0),
('university', 'MIT OpenCourseWare · AI & ML', 'MIT', 'Free lecture notes, exams, and assignments from MIT''s AI and machine learning courses.', 'material', 'Intermediate', '["mit","machine-learning","deep-learning","free"]', '["Self-paced","Multiple courses"]', 'https://ocw.mit.edu/search/?q=artificial+intelligence', 0),
('university', 'fast.ai · Practical Deep Learning for Coders', 'fast.ai', 'Top-down, code-first deep learning course — start building models on day one. 6M+ video views, endorsed by Peter Norvig.', 'material', 'Beginner', '["deep-learning","pytorch","practical","fast.ai"]', '["9 lessons","~90 min each"]', 'https://course.fast.ai/', 0),
('university', 'Neural Networks and Deep Learning', 'Michael Nielsen', 'Free online book offering deep intuition for neural networks and backprop with interactive visualizations.', 'material', 'Intermediate', '["neural-networks","backprop","book","free"]', '["Free book","Interactive"]', 'http://neuralnetworksanddeeplearning.com/', 0),
('university', 'Deep Learning', 'Goodfellow, Bengio & Courville', 'The definitive deep learning textbook covering fundamentals through advanced topics like GANs and sequence models.', 'material', 'Advanced', '["deep-learning","textbook","gans","rnn"]', '["Free online","MIT Press"]', 'https://www.deeplearningbook.org/', 0),
('university', 'Khan Academy · Math for AI', 'Khan Academy', 'Free courses on linear algebra, calculus, probability and statistics — the mathematical foundations for ML.', 'material', 'Beginner', '["math","linear-algebra","calculus","probability","free"]', '["Self-paced","Free"]', 'https://www.khanacademy.org/math', 0),
