('university', 'CS234 · Reinforcement Learning', 'Stanford University · Emma Brunskill', 'Stanford''s core RL course — MDPs, Q-learning, policy gradients, RLHF, and deep RL. Lecture videos on YouTube. Textbook is Sutton & Barto (free online).', 'material', 'Advanced', '["stanford","reinforcement-learning","rl","mdp","rlhf","free"]', '["Video + Notes","Advanced"]', 'https://cs234.stanford.edu/', 0),
('university', 'MIT 6.034 · Artificial Intelligence', 'MIT OpenCourseWare · Patrick Winston', 'Classic MIT undergrad AI course with full lecture videos. Covers search, constraint satisfaction, learning, neural nets, and vision — timeless foundations.', 'material', 'Intermediate', '["mit","ai","search","neural-networks","free","ocw"]', '["Full Video Course","Intermediate"]', 'https://ocw.mit.edu/courses/6-034-artificial-intelligence-fall-2010/', 0),
('university', 'MIT 6.867 · Machine Learning', 'MIT OpenCourseWare', 'MIT graduate ML course with comprehensive lecture notes and problem sets. Covers regression, classification, SVMs, HMMs, and Bayesian networks.', 'material', 'Advanced', '["mit","machine-learning","svm","hmm","bayesian","free","ocw"]', '["Lecture Notes","Graduate"]', 'https://ocw.mit.edu/courses/6-867-machine-learning-fall-2006/', 0),
('university', 'MIT 6.S191 · Introduction to Deep Learning', 'MIT · Alexander Amini', 'MIT''s intensive intro to deep learning with TensorFlow labs. Covers CNNs, RNNs, GANs, and reinforcement learning. Lectures free at introtodeeplearning.com.', 'material', 'Intermediate', '["mit","deep-learning","tensorflow","cnn","rnn","gan","free"]', '["Video + Labs","Intermediate"]', 'http://introtodeeplearning.com/', 0);
